provider "aws" {
  region = var.aws_region # From terraform.tfvars
}

provider "aws" {
  region = var.aws_region # Set in variables.tf and terraform.tfvars

  default_tags {
    tags = {
      project     = var.project
      environment = var.environment
      managed_by  = "terraform"
    }
  }
}

provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}

resource "aws_s3_bucket" "website" {
  bucket = var.bucket_name # Name must be globally unique across all of AWS

  tags = merge(var.tags, {
    Name = var.bucket_name
  })
}

resource "aws_s3_bucket_policy" "cloudfront_oac" {
  bucket = aws_s3_bucket.website.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudFrontServicePrincipal"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com" # Only CloudFront service
        }
        Action   = "s3:GetObject"                   # Only READ permission (not write, delete, etc.)
        Resource = "${aws_s3_bucket.website.arn}/*" # All objects in bucket
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.website.arn
            # SECURITY: Only THIS specific CloudFront distribution
            #           Not CloudFront in general, not other distributions
          }
        }
      }
    ]
  })

  depends_on = [
    aws_s3_bucket_public_access_block.website,
    aws_cloudfront_origin_access_control.website
  ]
}

resource "aws_s3_bucket_policy" "cloudfront_oac" {
  bucket = aws_s3_bucket.website.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudFrontServicePrincipal"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com" # Only CloudFront service
        }
        Action   = "s3:GetObject"                   # Only READ permission (not write, delete, etc.)
        Resource = "${aws_s3_bucket.website.arn}/*" # All objects in bucket
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.website.arn
            # SECURITY: Only THIS specific CloudFront distribution
            #           Not CloudFront in general, not other distributions
          }
        }
      }
    ]
  })

  depends_on = [
    aws_s3_bucket_public_access_block.website,
    aws_cloudfront_origin_access_control.website
  ]
}

resource "aws_iam_policy" "terraform_dev_policy" {
